143	        var columnsWithIndex = columns.Select((k, i) => (col: k, idx: i));
144	        var updateColumnsWithParams = string.Join(", ", columnsWithIndex.Where(c => c.col != keyColumn).Select(c => $"\"{c.col}\"=${c.idx + 1}"));
145	        var commandText = $"""
146	INSERT INTO {schema}."{tableName}" ({columnNames})
147	VALUES ({valuesParams})
148	ON CONFLICT ("{keyColumn}")
149	DO UPDATE SET {updateColumnsWithParams};
150	""";
151	
152	        return new PostgresSqlCommandInfo(commandText)
153	        {
154	            Parameters = columns.Select(c =>
155	                PostgresVectorStoreRecordPropertyMapping.GetNpgsqlParameter(row[c])
156	            ).ToList()
157	        };
158	    }
