7	namespace Microsoft.SemanticKernel.Connectors.Postgres;
8	
9	/// <summary>
10	/// Represents a SQL command for Postgres.
11	/// </summary>
12	internal class PostgresSqlCommandInfo
13	{
14	    /// <summary>
15	    /// Gets or sets the SQL command text.
16	    /// </summary>
17	    public string CommandText { get; set; }
18	    /// <summary>
19	    /// Gets or sets the parameters for the SQL command.
20	    /// </summary>
21	    public List<NpgsqlParameter>? Parameters { get; set; } = null;
22	
23	    /// <summary>
24	    /// Initializes a new instance of the <see cref="PostgresSqlCommandInfo"/> class.
25	    /// </summary>
26	    /// <param name="commandText">The SQL command text.</param>
27	    /// <param name="parameters">The parameters for the SQL command.</param>
28	    public PostgresSqlCommandInfo(string commandText, List<NpgsqlParameter>? parameters = null)
29	    {
30	        this.CommandText = commandText;
31	        this.Parameters = parameters;
32	    }
33	
34	    /// <summary>
35	    /// Converts this instance to an <see cref="NpgsqlCommand"/>.
36	    /// </summary>
37	    [SuppressMessage("Security", "CA2100:Review SQL queries for security vulnerabilities", Justification = "User input is passed using command parameters.")]
38	    public NpgsqlCommand ToNpgsqlCommand(NpgsqlConnection connection, NpgsqlTransaction? transaction = null)
39	    {
40	        NpgsqlCommand cmd = connection.CreateCommand();
41	        if (transaction != null)
42	        {
43	            cmd.Transaction = transaction;
44	        }
45	        cmd.CommandText = this.CommandText;
46	        if (this.Parameters != null)
47	        {
48	            foreach (var parameter in this.Parameters)
49	            {
50	                cmd.Parameters.Add(parameter);
51	            }
52	        }
53	        return cmd;
54	    }
55	}
