38	    /// <inheritdoc />
39	    public async Task<bool> DoesTableExistsAsync(string tableName, CancellationToken cancellationToken = default)
40	    {
41	        NpgsqlConnection connection = await this.DataSource.OpenConnectionAsync(cancellationToken).ConfigureAwait(false);
42	
43	        await using (connection)
44	        {
45	            var commandInfo = this._sqlBuilder.BuildDoesTableExistCommand(this._schema, tableName);
46	            using NpgsqlCommand cmd = commandInfo.ToNpgsqlCommand(connection);
47	            using NpgsqlDataReader dataReader = await cmd.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);
48	            if (await dataReader.ReadAsync(cancellationToken).ConfigureAwait(false))
49	            {
50	                return dataReader.GetString(dataReader.GetOrdinal("table_name")) == tableName;
51	            }
52	
53	            return false;
54	        }
55	    }
