74	    /// <inheritdoc />
75	    public async Task CreateTableAsync(string tableName, VectorStoreRecordModel model, bool ifNotExists = true, CancellationToken cancellationToken = default)
76	    {
77	        // Prepare the SQL commands.
78	        var commandInfo = this._sqlBuilder.BuildCreateTableCommand(this._schema, tableName, model, ifNotExists);
79	        var createIndexCommands =
80	            PostgresVectorStoreRecordPropertyMapping.GetIndexInfo(model.Properties)
81	                .Select(index =>
82	                    this._sqlBuilder.BuildCreateIndexCommand(this._schema, tableName, index.column, index.kind, index.function, index.isVector, ifNotExists));
83	
84	        // Execute the commands in a transaction.
85	        NpgsqlConnection connection = await this.DataSource.OpenConnectionAsync(cancellationToken).ConfigureAwait(false);
86	
87	        await using (connection)
88	        {
89	#if NET8_0_OR_GREATER
90	            var transaction = await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);
91	            await using (transaction)
92	#else
93	            var transaction = connection.BeginTransaction();
94	            using (transaction)
95	#endif
96	            {
97	                using NpgsqlCommand cmd = commandInfo.ToNpgsqlCommand(connection, transaction);
98	                await cmd.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
99	
100	                foreach (var createIndexCommand in createIndexCommands)
101	                {
102	                    using NpgsqlCommand indexCmd = createIndexCommand.ToNpgsqlCommand(connection, transaction);
103	                    await indexCmd.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
104	                }
105	
106	#if NET8_0_OR_GREATER
107	                await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
108	#else
109	                transaction.Commit();
110	#endif
111	            }
112	        }
113	    }
